def minStable(nums, maxC):
    import math
    n = len(nums)
    # Sparse table of range GCDs
    sp = [nums[:]]
    j = 1
    while (1 << j) <= n:
        prev = sp[-1]
        half = 1 << (j - 1)
        cur = [0] * (n - (1 << j) + 1)
        for i in range(len(cur)):
            cur[i] = math.gcd(prev[i], prev[i + half])
        sp.append(cur)
        j += 1

    def win_gcd(l, r):
        length = r - l + 1
        kk = length.bit_length() - 1
        return math.gcd(sp[kk][l], sp[kk][r - (1 << kk) + 1])

    def feasible(m):
        # can every window of length m+1 get gcd 1 with at most maxC changes?
        w = m + 1
        if w > n:
            return True
        breakers = 0
        last = -1  # last modified index
        for i in range(0, n - w + 1):
            if last < i and win_gcd(i, i + w - 1) >= 2:
                last = i + w - 1
                breakers += 1
                if breakers > maxC:
                    return False
        return True

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
